<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { neon, signInWithGoogle } from './neon'
import { AdminService, type AcademicPeriod, type BulkOfferingResult, type BulkOfferingRow, type Category, type ManagedCourse, type MergePreview, type ModerationAuditEntry, type ModerationReview, type OfferingImportPreview, type PendingProposal, type RoleAssignment, type VerifiedAccount } from './services/admin'
import { ReviewService, type VisibleReview } from './services/reviews'
import { TimetableService } from './services/timetable-client'
import { isValidMeeting, overlaps, type Meeting } from './services/timetable'
import { ProposalService, type OfferingProposal } from './services/proposals'
import LegacyTimetableImport from './components/LegacyTimetableImport.vue'
import { readLegacyTimetable, type LegacySource } from './services/legacy-timetable-import'

type Course = { id: string; code: string; name_th: string; category_name: string }
type Offering = { id: string; section: string; academic_year: number; semester: string; instructor_name: string | null }
type TimetableEntry = { offering_id: string | null; review_id: string | null; source: 'official' | 'reported'; course_code: string; course_name: string; section: string; day_of_week: number; starts_at: string; ends_at: string }
const courses = ref<Course[]>([]); const offerings = ref<Offering[]>([]); const reviews = ref<VisibleReview[]>([])
const offeringMeetings = ref<Record<string, Meeting[]>>({})
const selected = ref<Course | null>(null); const rating = ref(5); const text = ref(''); const error = ref(''); const loading = ref(true); const signedIn = ref(false); const publishing = ref(false)
const reviewFormOpen = ref(false)
const reviewSemester = ref(''); const reviewYear = ref(0); const reviewTeacher = ref(''); const reviewSection = ref(''); const reviewDay = ref('จันทร์'); const reviewStart = ref(''); const reviewEnd = ref('')
const service = computed(() => neon ? new ReviewService(neon as any) : null)
const adminService = computed(() => neon ? new AdminService(neon as any) : null)
const timetableService = computed(() => neon ? new TimetableService(neon as any) : null)
const proposalService = computed(() => neon ? new ProposalService(neon as any) : null)
const accessRole = ref<'owner' | 'administrator' | null>(null); const dashboard = ref(false)
const accountMenuOpen = ref(false); const contactOpen = ref(false); const displayName = ref('บัญชีของฉัน')
const signedInEmail = ref('')
const legacySource = ref<LegacySource>({ kind: 'none' })
const timetable = ref(false); const timetableEntries = ref<TimetableEntry[]>([])
const myReviewsScreen = ref(false); const myReviews = ref<import('./services/reviews').MyReview[]>([])
const reviewHistoryId = ref<string | null>(null); const reviewHistory = ref<import('./services/reviews').ReviewRevision[]>([])
const editingReviewId = ref<string | null>(null); const editReviewRating = ref(5); const editReviewText = ref('')
const members = ref<RoleAssignment[]>([]); const verifiedAccounts = ref<VerifiedAccount[]>([])
const categories = ref<Category[]>([]); const categoryName = ref(''); const courseCode = ref(''); const courseName = ref(''); const courseCategoryId = ref('')
const managedCourses = ref<ManagedCourse[]>([]); const editingCourseId = ref<string | null>(null)
const mergeSourceId = ref(''); const mergeTargetId = ref(''); const mergePreview = ref<MergePreview | null>(null)
const periods = ref<AcademicPeriod[]>([]); const periodYear = ref(new Date().getFullYear() + 543); const periodSemester = ref('1'); const offeringCourseId = ref(''); const offeringYear = ref(new Date().getFullYear() + 543); const offeringSemester = ref('1'); const offeringSection = ref(''); const offeringInstructor = ref(''); const offeringDay = ref(1); const offeringStart = ref('09:00'); const offeringEnd = ref('12:00')
const editingOfferingId = ref<string | null>(null); const courseOfferings = ref<Offering[]>([])
const bulkImportText = ref(''); const bulkImportPreview = ref<OfferingImportPreview[]>([]); const bulkImportResult = ref<BulkOfferingResult | null>(null)
const proposals = ref<PendingProposal[]>([]); const proposalYear = ref(new Date().getFullYear() + 543); const proposalSemester = ref('1'); const proposalSection = ref(''); const proposalInstructor = ref(''); const myProposals = ref<OfferingProposal[]>([])
const searchTerm = ref(''); const categoryFilter = ref('')
const reviewRatingFilter = ref(0); const reviewSemesterFilter = ref(''); const reviewYearFilter = ref(0)
const moderationReviews = ref<ModerationReview[]>([]); const moderationState = ref<'all' | ModerationReview['moderation_state']>('all'); const moderationSearch = ref(''); const moderationReasons = ref<Record<string, string>>({})
const moderationAuditId = ref<string | null>(null); const moderationAudit = ref<ModerationAuditEntry[]>([])
const filteredCourses = computed(() => courses.value.filter((course) => {
  const search = searchTerm.value.trim().toLowerCase()
  return (!search || `${course.code} ${course.name_th}`.toLowerCase().includes(search)) && (!categoryFilter.value || course.category_name === categoryFilter.value)
}))
async function loadCatalog() {
  if (!neon) { loading.value = false; error.value = 'ตั้งค่า Neon endpoint ใน .env.local ก่อนใช้งาน'; return }
  const { data, error: apiError } = await (neon as any).rpc('list_approved_catalog')
  if (apiError) error.value = apiError.message; else courses.value = data ?? []
  loading.value = false
}
async function openCourse(course: Course) {
  selected.value = course; reviewFormOpen.value = false; error.value = ''; reviews.value = []; offerings.value = []; offeringMeetings.value = {}
  const { data, error: apiError } = await (neon as any).rpc('list_approved_offerings', { p_course_id: course.id })
  if (apiError) error.value = apiError.message
  offerings.value = data ?? []
  await Promise.all(offerings.value.map(async (offering) => {
    try {
      const result = await (neon as any).rpc('list_approved_offering_meetings', { p_offering_id: offering.id })
      if (result.error) throw new Error(result.error.message)
      offeringMeetings.value[offering.id] = ((result.data ?? []) as Array<{ day_of_week: number; starts_at: string; ends_at: string }>).map((row) => ({ day: row.day_of_week, start: timeValue(row.starts_at), end: timeValue(row.ends_at) })).filter(isValidMeeting)
    } catch { offeringMeetings.value[offering.id] = [] }
  }))
  reviewSemester.value = offerings.value[0]?.semester ?? ''; reviewYear.value = offerings.value[0]?.academic_year ?? 0; reviewTeacher.value = offerings.value[0]?.instructor_name ?? ''; reviewSection.value = offerings.value[0]?.section ?? ''; reviewDay.value = 'จันทร์'; reviewStart.value = ''; reviewEnd.value = ''
  await Promise.all([loadReviews(course.id), loadMyProposals(), loadTimetable().catch((cause) => { timetableEntries.value = []; error.value = cause instanceof Error ? cause.message : 'ไม่สามารถโหลดตารางเรียนได้' })])
}
async function loadReviews(courseId = selected.value?.id) {
  if (!courseId || !service.value) return
  try {
    reviews.value = await service.value.listVisible(courseId, { rating: reviewRatingFilter.value || undefined, semester: reviewSemesterFilter.value || undefined, academicYear: reviewYearFilter.value || undefined })
  } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถโหลดรีวิวได้' }
}
async function loadTimetable() { if (!timetableService.value) return; timetableEntries.value = await timetableService.value.list() as TimetableEntry[] }
async function refreshTimetableAfterImport() { try { await loadTimetable() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถโหลดตารางเรียนหลังนำเข้าได้' } }
async function openTimetable() { timetable.value = true; dashboard.value = false; selected.value = null; error.value = ''; try { await loadTimetable() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถโหลดตารางเรียนได้' } }
const dayNames = ['','จันทร์','อังคาร','พุธ','พฤหัสบดี','ศุกร์','เสาร์','อาทิตย์']
function timeValue(time: string) { return time.slice(0, 5) }
function reviewOffering(review: VisibleReview): Offering | null {
  if (!review.section || !review.semester || !review.academicYear) return null
  const matches = offerings.value.filter((offering) => offering.academic_year === review.academicYear && offering.semester === review.semester && normalizedSection(offering.section) === normalizedSection(review.section!))
  return matches.length === 1 && offeringMeetings.value[matches[0].id]?.length ? matches[0] : null
}
function normalizedSection(value: string) { return value.trim().replace(/\s+/g, '').toLocaleLowerCase() }
function isSelected(offering: Offering): boolean { return timetableEntries.value.some((entry) => entry.offering_id === offering.id) }
function hasReportedTime(review: VisibleReview): boolean {
  return !!review.section?.trim() && !!review.semester && !!review.academicYear && !!review.dayOfWeek && !!review.startsAt && !!review.endsAt && isValidMeeting({ day: review.dayOfWeek, start: timeValue(review.startsAt), end: timeValue(review.endsAt) })
}
function isReviewSelected(review: VisibleReview): boolean {
  const offering = reviewOffering(review)
  return (offering ? isSelected(offering) : false) || timetableEntries.value.some((entry) => entry.review_id === review.id)
}
async function addReviewToTimetable(review: VisibleReview) {
  const offering = reviewOffering(review)
  if (offering) { await addToTimetable(offering, review); return }
  if (!hasReportedTime(review) || !timetableService.value || !selected.value) return
  error.value = ''
  try {
    await loadTimetable()
    if (timetableEntries.value.some((entry) => entry.review_id === review.id)) return
    const currentCourse = timetableEntries.value.filter((entry) => entry.course_code === selected.value!.code)
    const conflicts = timetableEntries.value.filter((entry) => entry.course_code !== selected.value!.code && overlaps(
      { day: review.dayOfWeek!, start: timeValue(review.startsAt!), end: timeValue(review.endsAt!) },
      { day: entry.day_of_week, start: timeValue(entry.starts_at), end: timeValue(entry.ends_at) }))
    const messages = [currentCourse.length ? `มี ${selected.value.code} อยู่แล้ว ระบบจะเปลี่ยนเป็นกลุ่ม ${review.section}` : '',
      conflicts.length ? `เวลาเรียนชนกับ ${[...new Set(conflicts.map((entry) => entry.course_code))].join(', ')}` : ''].filter(Boolean)
    if (messages.length && !window.confirm(`${messages.join('\n')}\nต้องการดำเนินการต่อหรือไม่?`)) return
    await timetableService.value.addReview(review.id)
    await loadTimetable()
    if (!window.confirm(`✅ เพิ่ม ${selected.value.code} ลงตารางเรียนแล้ว!\nต้องการไปดูหน้าตารางเรียนของคุณตอนนี้เลยไหม?`)) return
    timetable.value = true; selected.value = null
  } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถเพิ่มลงตารางเรียนได้' }
}
function reviewDate(value: string): string { const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : date.toLocaleDateString('th-TH') }
function courseColor(code: string) { return `timetable-color-${(code.charCodeAt(0) + code.charCodeAt(code.length - 1)) % 6}` }
function timetableStyle(entry: TimetableEntry) { const start = Number(timeValue(entry.starts_at).slice(0,2)) * 60 + Number(timeValue(entry.starts_at).slice(3)); const end = Number(timeValue(entry.ends_at).slice(0,2)) * 60 + Number(timeValue(entry.ends_at).slice(3)); return { left: `${Math.max(0, ((start - 480) / 720) * 100)}%`, width: `${Math.min(100, ((end - start) / 720) * 100)}%` } }
async function addToTimetable(offering: Offering, review?: VisibleReview) {
  if (!timetableService.value || !selected.value) return
  error.value = ''
  try {
    const available = await (neon as any).rpc('list_approved_offerings', { p_course_id: selected.value.id })
    if (available.error) throw new Error(available.error.message)
    const latest = (available.data ?? []) as Offering[]
    if (!latest.some((item) => item.id === offering.id)) throw new Error('กลุ่มเรียนนี้ไม่ได้เปิดให้เพิ่มลงตารางแล้ว')
    if (review) {
      const matches = latest.filter((item) => item.academic_year === review.academicYear && item.semester === review.semester && normalizedSection(item.section) === normalizedSection(review.section ?? ''))
      if (matches.length !== 1 || matches[0].id !== offering.id) throw new Error('รีวิวนี้ไม่ตรงกับกลุ่มเรียนที่อนุมัติแล้ว')
    }
    const result = await (neon as any).rpc('list_approved_offering_meetings', { p_offering_id: offering.id })
    if (result.error) throw new Error(result.error.message)
    const meetings = ((result.data ?? []) as Array<{ day_of_week: number; starts_at: string; ends_at: string }>).filter((row) => isValidMeeting({ day: row.day_of_week, start: timeValue(row.starts_at), end: timeValue(row.ends_at) }))
    if (!meetings.length) throw new Error('รายวิชานี้ไม่มีเวลาเรียนที่ใช้งานได้')
    if (review) {
      const latestMeetings = meetings.map((meeting) => ({ day: meeting.day_of_week, start: timeValue(meeting.starts_at), end: timeValue(meeting.ends_at) }))
      if (JSON.stringify(offeringMeetings.value[offering.id]) !== JSON.stringify(latestMeetings)) {
        offeringMeetings.value[offering.id] = latestMeetings
        throw new Error('เวลาเรียนทางการเปลี่ยนไป โปรดตรวจสอบเวลาใหม่ก่อนเพิ่มลงตาราง')
      }
    }
    await loadTimetable()
    if (isSelected(offering)) return
    const currentCourse = timetableEntries.value.filter((entry) => entry.course_code === selected.value!.code)
    const conflicts = timetableEntries.value.filter((entry) => entry.course_code !== selected.value!.code && meetings.some((meeting) => overlaps({ day: meeting.day_of_week, start: timeValue(meeting.starts_at), end: timeValue(meeting.ends_at) }, { day: entry.day_of_week, start: timeValue(entry.starts_at), end: timeValue(entry.ends_at) })))
    const messages = [currentCourse.length ? `มี ${selected.value.code} อยู่แล้ว ระบบจะเปลี่ยนเป็นกลุ่ม ${offering.section}` : '', conflicts.length ? `เวลาเรียนชนกับ ${[...new Set(conflicts.map((entry) => entry.course_code))].join(', ')}` : ''].filter(Boolean)
    if (messages.length && !window.confirm(`${messages.join('\n')}\nต้องการดำเนินการต่อหรือไม่?`)) return
    if (currentCourse.length) await timetableService.value.replace(offering.id); else await timetableService.value.add(offering.id)
    await loadTimetable()
    if (review && !window.confirm(`✅ เพิ่ม ${selected.value.code} ลงตารางเรียนแล้ว!\nต้องการไปดูหน้าตารางเรียนของคุณตอนนี้เลยไหม?`)) return
    timetable.value = true; selected.value = null
  } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถเพิ่มลงตารางเรียนได้' }
}
async function removeFromTimetable(entry: TimetableEntry) { if (!timetableService.value) return; try { if (entry.source === 'reported' && entry.review_id) await timetableService.value.removeReview(entry.review_id); else if (entry.offering_id) await timetableService.value.remove(entry.offering_id); await loadTimetable() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถลบรายวิชาได้' } }
async function clearTimetable() { if (!timetableService.value || !window.confirm('ต้องการล้างตารางเรียนทั้งหมดใช่หรือไม่?')) return; try { await timetableService.value.clear(); await loadTimetable() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถล้างตารางเรียนได้' } }
async function openMyReviews() { if (!service.value) return; myReviewsScreen.value = true; timetable.value = false; dashboard.value = false; error.value = ''; try { myReviews.value = await service.value.listMine() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถโหลดรีวิวของฉันได้' } }
async function setMyReviewActive(id: string, active: boolean) { if (!service.value) return; try { await service.value.setMineActive(id, active); myReviews.value = await service.value.listMine() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถเปลี่ยนสถานะรีวิวได้' } }
function beginReviewEdit(review: import('./services/reviews').MyReview) { editingReviewId.value = review.id; editReviewRating.value = review.rating; editReviewText.value = review.text; error.value = '' }
function cancelReviewEdit() { editingReviewId.value = null; editReviewText.value = '' }
async function saveReviewEdit() { if (!service.value || !editingReviewId.value) return; try { await service.value.updateMine(editingReviewId.value, editReviewRating.value, editReviewText.value); myReviews.value = await service.value.listMine(); cancelReviewEdit() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถแก้ไขรีวิวได้' } }
async function toggleReviewHistory(reviewId: string) { if (reviewHistoryId.value === reviewId) { reviewHistoryId.value = null; return }; if (!service.value) return; try { reviewHistory.value = await service.value.listMyRevisions(reviewId); reviewHistoryId.value = reviewId } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถโหลดประวัติการแก้ไขได้' } }
async function publish() {
  if (!selected.value) { error.value = 'กรุณาเลือกรายวิชา'; return }
  if (!service.value) { error.value = 'ยังไม่ได้เชื่อมต่อบริการรีวิว กรุณาเข้าสู่ระบบใหม่อีกครั้ง'; return }
  error.value = ''
  publishing.value = true
  try {
    await service.value.create(selected.value.id, { academicYear: reviewYear.value, semester: reviewSemester.value, section: reviewSection.value, instructorName: reviewTeacher.value, dayOfWeek: dayNames.indexOf(reviewDay.value), startsAt: reviewStart.value, endsAt: reviewEnd.value }, rating.value, text.value)
    text.value = ''; reviewFormOpen.value = false; await loadReviews(selected.value.id)
  } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถเผยแพร่รีวิวได้' } finally { publishing.value = false }
}
async function enter() { try { await signInWithGoogle() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถเริ่มการเข้าสู่ระบบได้' } }
async function loadAccess() {
  const { data, error: apiError } = await (neon as any).rpc('current_access')
  if (apiError) throw new Error(apiError.message)
  accessRole.value = data?.[0]?.role ?? null
}
async function openDashboard() {
  if (!accessRole.value) return
  dashboard.value = true; error.value = ''
  if (adminService.value) {
    try {
      categories.value = await adminService.value.listCategories()
      managedCourses.value = await adminService.value.listManageableCourses()
      periods.value = await adminService.value.listAcademicPeriods()
      proposals.value = await adminService.value.listPendingOfferingProposals()
      moderationReviews.value = await adminService.value.listModerationReviews()
      if (!courseCategoryId.value && categories.value[0]) courseCategoryId.value = categories.value[0].id
      if (accessRole.value === 'owner') {
        ;[members.value, verifiedAccounts.value] = await Promise.all([adminService.value.listRoleAssignments(), adminService.value.listVerifiedAccounts()])
      }
    } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถโหลดข้อมูลผู้ดูแลได้' }
  }
}
async function addCategory() { if (!adminService.value || !categoryName.value.trim()) return; try { await adminService.value.createCategory(categoryName.value); categoryName.value = ''; await openDashboard() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถเพิ่มหมวดหมู่ได้' } }
async function renameCategory(category: Category) { const name = window.prompt('ชื่อหมวดหมู่', category.name); if (!adminService.value || !name?.trim()) return; try { await adminService.value.updateCategory(category.id, name); await Promise.all([openDashboard(), loadCatalog()]) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถแก้ไขหมวดหมู่ได้' } }
async function addCourse() { if (!adminService.value) return; try { const draft = { code: courseCode.value, nameTh: courseName.value, categoryId: courseCategoryId.value }; if (editingCourseId.value) await adminService.value.updateCourse(editingCourseId.value, draft); else await adminService.value.createCourse(draft); courseCode.value = ''; courseName.value = ''; editingCourseId.value = null; await Promise.all([openDashboard(), loadCatalog()]) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถบันทึกรายวิชาได้' } }
function editCourse(course: ManagedCourse) { editingCourseId.value = course.id; courseCode.value = course.code; courseName.value = course.name_th; courseCategoryId.value = course.category_id }
async function archiveCourse(courseId: string) { if (!adminService.value) return; try { await adminService.value.archiveCourse(courseId); await Promise.all([openDashboard(), loadCatalog()]) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถปิดใช้งานรายวิชาได้' } }
async function previewMerge() { if (!adminService.value || !mergeSourceId.value || !mergeTargetId.value) return; try { mergePreview.value = await adminService.value.previewCourseMerge(mergeSourceId.value, mergeTargetId.value) } catch (cause) { mergePreview.value = null; error.value = cause instanceof Error ? cause.message : 'ไม่สามารถตรวจสอบการรวมรายวิชาได้' } }
async function confirmMerge() { if (!adminService.value || !mergePreview.value || !window.confirm(`รวม ${mergePreview.value.source_code} เข้ากับ ${mergePreview.value.target_code} ใช่หรือไม่?`)) return; try { await adminService.value.mergeCourse(mergeSourceId.value, mergeTargetId.value); mergePreview.value = null; mergeSourceId.value = ''; mergeTargetId.value = ''; await Promise.all([openDashboard(), loadCatalog()]) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถรวมรายวิชาได้' } }
async function addPeriod() { if (!adminService.value) return; try { await adminService.value.createAcademicPeriod(periodYear.value, periodSemester.value); await openDashboard() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถเพิ่มภาคการศึกษาได้' } }
async function addOffering() { if (!adminService.value) return; try { const draft = { courseId: offeringCourseId.value, academicYear: offeringYear.value, semester: offeringSemester.value, section: offeringSection.value, instructorName: offeringInstructor.value, day: offeringDay.value, startsAt: offeringStart.value, endsAt: offeringEnd.value }; if (editingOfferingId.value) await adminService.value.updateOffering(editingOfferingId.value, draft); else await adminService.value.createOffering(draft); offeringSection.value = ''; offeringInstructor.value = ''; editingOfferingId.value = null; await Promise.all([openDashboard(), loadCourseOfferings()]) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถบันทึกกลุ่มเรียนได้' } }
async function loadCourseOfferings() { editingOfferingId.value = null; if (!offeringCourseId.value || !adminService.value) { courseOfferings.value = []; return }; try { courseOfferings.value = await adminService.value.listOfferings(offeringCourseId.value) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถโหลดกลุ่มเรียนได้' } }
async function editOffering(offering: Offering) { editingOfferingId.value = offering.id; offeringYear.value = offering.academic_year; offeringSemester.value = offering.semester; offeringSection.value = offering.section; offeringInstructor.value = offering.instructor_name ?? ''; try { const result = await (neon as any).rpc('list_approved_offering_meetings', { p_offering_id: offering.id }); if (result.error) throw new Error(result.error.message); const meeting = ((result.data ?? []) as Array<{ day_of_week: number; starts_at: string; ends_at: string }>)[0]; if (meeting) { offeringDay.value = meeting.day_of_week; offeringStart.value = timeValue(meeting.starts_at); offeringEnd.value = timeValue(meeting.ends_at) } } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถโหลดเวลาเรียนได้' } }
function parseBulkImportRows(): unknown[] { const parsed = JSON.parse(bulkImportText.value); if (!Array.isArray(parsed)) throw new Error('ข้อมูลต้องเป็นรายการ (array) ของกลุ่มเรียน'); return parsed }
async function previewBulkImport() { if (!adminService.value) return; bulkImportResult.value = null; try { bulkImportPreview.value = await adminService.value.previewOfferingImport(parseBulkImportRows()) } catch (cause) { bulkImportPreview.value = []; error.value = cause instanceof Error ? cause.message : 'ไม่สามารถตรวจสอบข้อมูลนำเข้าได้' } }
async function confirmBulkImport() { if (!adminService.value) return; try { bulkImportResult.value = await adminService.value.bulkImportOfferings(parseBulkImportRows() as BulkOfferingRow[]); bulkImportPreview.value = []; bulkImportText.value = ''; await Promise.all([openDashboard(), loadCourseOfferings()]) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถนำเข้ากลุ่มเรียนได้' } }
async function submitProposal() { if (!selected.value || !proposalService.value) return; try { await proposalService.value.create(selected.value.id, proposalYear.value, proposalSemester.value, proposalSection.value, proposalInstructor.value); proposalSection.value = ''; proposalInstructor.value = ''; await loadMyProposals() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถส่งข้อเสนอกลุ่มเรียนได้' } }
async function loadMyProposals() { if (!proposalService.value) return; try { myProposals.value = await proposalService.value.listMine() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถโหลดข้อเสนอของฉันได้' } }
async function resolveProposal(id: string, approve: boolean) { if (!adminService.value) return; try { await adminService.value.resolveOfferingProposal(id, approve); await openDashboard() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถดำเนินการข้อเสนอได้' } }
async function loadModerationReviews() { if (!adminService.value) return; try { moderationReviews.value = await adminService.value.listModerationReviews(moderationState.value === 'all' ? undefined : moderationState.value) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถโหลดรีวิวสำหรับตรวจสอบได้' } }
const visibleModerationReviews = computed(() => { const query = moderationSearch.value.trim().toLowerCase(); return !query ? moderationReviews.value : moderationReviews.value.filter((review) => review.text.toLowerCase().includes(query)) })
function moderationStateLabel(state: ModerationReview['moderation_state']) { return state === 'visible' ? 'เผยแพร่' : state === 'hidden' ? 'ซ่อน' : 'นำออก' }
async function toggleModerationAudit(reviewId: string) { if (moderationAuditId.value === reviewId) { moderationAuditId.value = null; return }; if (!adminService.value) return; try { moderationAudit.value = await adminService.value.listModerationAudit(reviewId); moderationAuditId.value = reviewId } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถโหลดประวัติการตรวจสอบได้' } }
async function moderateReview(id: string, state: ModerationReview['moderation_state']) { if (!adminService.value) return; try { await adminService.value.moderateReview(id, state, moderationReasons.value[id] ?? ''); moderationReasons.value[id] = ''; await loadModerationReviews(); if (moderationAuditId.value === id) moderationAudit.value = await adminService.value.listModerationAudit(id) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถเปลี่ยนสถานะรีวิวได้' } }
async function grantAdministrator(userId: string) {
  if (!adminService.value) return
  try { await adminService.value.grantAdministrator(userId); await openDashboard() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถกำหนดสิทธิ์ผู้ดูแลได้' }
}
async function revokeAdministrator(userId: string) {
  if (!adminService.value) return
  try { await adminService.value.revokeAdministrator(userId); await openDashboard() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'ไม่สามารถถอนสิทธิ์ผู้ดูแลได้' }
}
async function signOut() {
  await neon?.auth.signOut()
  signedIn.value = false
  courses.value = []
  offerings.value = []
  reviews.value = []
  selected.value = null
  accessRole.value = null
  dashboard.value = false
  timetable.value = false
  myReviewsScreen.value = false
  members.value = []
  verifiedAccounts.value = []
  error.value = ''
  accountMenuOpen.value = false
  contactOpen.value = false
  displayName.value = 'บัญชีของฉัน'
  signedInEmail.value = ''
  legacySource.value = { kind: 'none' }
}
onMounted(async () => {
  if (!neon) { loading.value = false; return }
  try {
    const session = await (neon.auth as any).getSession()
    signedIn.value = Boolean(session?.data?.user)
    if (signedIn.value) {
      const user = session.data.user
      displayName.value = user.name || user.email?.split('@')[0] || 'บัญชีของฉัน'
      signedInEmail.value = user.email ?? ''
      if (signedInEmail.value) {
        try { legacySource.value = readLegacyTimetable(signedInEmail.value, window.localStorage) }
        catch { legacySource.value = { kind: 'error', message: 'อ่านข้อมูลตารางเรียนเดิมจากเบราว์เซอร์ไม่ได้' } }
      }
      await Promise.all([loadCatalog(), loadAccess(), adminService.value?.listCategories().then((items) => { categories.value = items })])
    } else loading.value = false
  } catch (cause) {
    signedIn.value = false
    loading.value = false
    error.value = cause instanceof Error ? cause.message : 'ไม่สามารถตรวจสอบสถานะการเข้าสู่ระบบได้'
  }
})
</script>

<template>
  <main>
    <nav v-if="signedIn" class="navbar navbar-custom navbar-dark mb-4"><div class="container d-flex justify-content-between align-items-center"><button class="navbar-brand mb-0 h1 border-0 bg-transparent" @click="timetable = false; dashboard = false; myReviewsScreen = false; selected = null"><i class="bi bi-journal-text me-2"></i>Varasarn Close Friends</button><div class="d-flex align-items-center gap-2"><button class="btn btn-sm btn-light text-purple fw-bold rounded-pill px-3 shadow-sm" @click="openTimetable"><i class="bi bi-grid-3x3-gap-fill me-1"></i>ตารางเรียน<span v-if="legacySource.kind === 'found'" class="badge bg-warning text-dark ms-1">เดิม</span></button><div class="account-menu d-none d-md-block"><button class="btn user-dropdown-btn dropdown-toggle" type="button" :aria-expanded="accountMenuOpen" @click="accountMenuOpen = !accountMenuOpen"><i class="bi bi-person-circle me-1"></i>{{ displayName }}</button><div v-if="accountMenuOpen" class="account-menu-list dropdown-menu-custom"><button class="dropdown-item py-2" @click="accountMenuOpen = false; openMyReviews()"><i class="bi bi-star-fill text-warning me-2"></i>รีวิวของฉัน</button><button v-if="accessRole" class="dropdown-item py-2" @click="accountMenuOpen = false; openDashboard()">แดชบอร์ดผู้ดูแล</button><hr class="dropdown-divider"><button class="dropdown-item py-2 text-danger fw-bold" @click="accountMenuOpen = false; signOut()"><i class="bi bi-box-arrow-right me-2"></i>ออกจากระบบ</button></div></div></div></div></nav>
    <section v-if="!signedIn" class="sign-in"><div class="login-shell"><div class="login-card"><div class="login-banner"><img src="https://i.postimg.cc/FFk3NRHV/IMG-0677.jpg" alt="Varasarn Close Friends"></div><p class="login-description">พื้นที่รวบรวมรีวิววิชาเรียนและจัดตารางเรียนส่วนตัว<br>ดูแลโดย กน.วส.</p><div class="login-prompt">✨ กรุณาเข้าสู่ระบบด้วยบัญชี Google เพื่อใช้งานระบบ</div><button class="google-signin-btn" @click="enter"><svg class="google-mark" viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285F4" d="M21.35 12.27c0-.72-.06-1.42-.18-2.09H12v3.96h5.24a4.48 4.48 0 0 1-1.94 2.94v2.45h3.14c1.84-1.69 2.91-4.18 2.91-7.26Z"/><path fill="#34A853" d="M12 21.7c2.63 0 4.84-.87 6.45-2.36l-3.14-2.45c-.87.58-1.98.92-3.31.92-2.54 0-4.7-1.72-5.47-4.03H3.28v2.53A9.74 9.74 0 0 0 12 21.7Z"/><path fill="#FBBC05" d="M6.53 13.78A5.86 5.86 0 0 1 6.22 12c0-.62.11-1.22.31-1.78V7.69H3.28A9.73 9.73 0 0 0 2.25 12c0 1.57.38 3.05 1.03 4.31l3.25-2.53Z"/><path fill="#EA4335" d="M12 6.19c1.43 0 2.71.49 3.72 1.45l2.79-2.79C16.84 3.19 14.63 2.3 12 2.3a9.74 9.74 0 0 0-8.72 5.39l3.25 2.53C7.3 7.91 9.46 6.19 12 6.19Z"/></svg><span>เข้าสู่ระบบด้วย Google</span></button><p v-if="error" class="text-danger mt-3 mb-0" role="alert">{{ error }}</p></div></div></section>
    <section v-else class="container pb-5">
      <div v-if="!dashboard && !timetable && !myReviewsScreen" class="mobile-account-menu d-md-none mb-3"><button class="btn user-dropdown-btn dropdown-toggle w-100 text-start d-flex justify-content-between align-items-center" type="button" :aria-expanded="accountMenuOpen" @click="accountMenuOpen = !accountMenuOpen"><span><i class="bi bi-person-circle me-1"></i>{{ displayName }}</span></button><div v-if="accountMenuOpen" class="account-menu-list dropdown-menu-custom w-100"><button class="dropdown-item py-2" @click="accountMenuOpen = false; openMyReviews()"><i class="bi bi-star-fill text-warning me-2"></i>รีวิวของฉัน</button><button v-if="accessRole" class="dropdown-item py-2" @click="accountMenuOpen = false; openDashboard()">แดชบอร์ดผู้ดูแล</button><hr class="dropdown-divider"><button class="dropdown-item py-2 text-danger fw-bold" @click="accountMenuOpen = false; signOut()"><i class="bi bi-box-arrow-right me-2"></i>ออกจากระบบ</button></div></div>
      <section v-if="dashboard" class="review-box">
        <button class="btn btn-link text-purple p-0 mb-3" @click="dashboard = false">← กลับหน้ารายวิชา</button>
        <h1>แดชบอร์ดผู้ดูแล</h1><p v-if="error" class="text-danger" role="alert">{{ error }}</p>
        <h2 class="h4 mt-4">เพิ่มหมวดหมู่</h2><div class="input-group mb-3"><input v-model="categoryName" class="form-control" aria-label="ชื่อหมวดหมู่"><button class="btn btn-purple" @click="addCategory">เพิ่ม</button></div><div class="category-menu"><button v-for="category in categories" :key="category.id" class="btn category-btn btn-outline-purple" @click="renameCategory(category)">{{ category.name }} · แก้ไข</button></div>
        <h2 class="h4">{{ editingCourseId ? 'แก้ไขรายวิชา' : 'เพิ่มรายวิชา' }}</h2><div class="row g-2"><div class="col-md-3"><input v-model="courseCode" class="form-control" placeholder="รหัสวิชา"></div><div class="col-md-4"><input v-model="courseName" class="form-control" placeholder="ชื่อรายวิชา"></div><div class="col-md-3"><select v-model="courseCategoryId" class="form-select"><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.name }}</option></select></div><div class="col-md-2"><button class="btn btn-purple w-100" @click="addCourse">{{ editingCourseId ? 'บันทึก' : 'เพิ่มรายวิชา' }}</button></div></div>
        <h2 class="h4 mt-4">รายวิชา</h2><ul class="list-group"><li v-for="course in managedCourses" :key="course.id" class="list-group-item d-flex justify-content-between align-items-center"><span><strong>{{ course.code }}</strong> · {{ course.name_th }} <small class="text-muted">{{ course.category_name }} · {{ course.status }}</small></span><span class="d-flex gap-2"><button class="btn btn-sm btn-outline-purple" @click="editCourse(course)">แก้ไข</button><button v-if="course.status === 'approved'" class="btn btn-sm btn-outline-danger" @click="archiveCourse(course.id)">เก็บเข้าคลัง</button></span></li></ul>
        <h2 class="h4 mt-4">รวมรายวิชาซ้ำ</h2><div class="row g-2"><div class="col-md-5"><select v-model="mergeSourceId" class="form-select"><option value="">รายวิชาต้นทาง</option><option v-for="course in managedCourses.filter((course) => course.status === 'approved')" :key="course.id" :value="course.id">{{ course.code }} · {{ course.name_th }}</option></select></div><div class="col-md-5"><select v-model="mergeTargetId" class="form-select"><option value="">รายวิชาที่เก็บไว้</option><option v-for="course in managedCourses.filter((course) => course.status === 'approved' && course.id !== mergeSourceId)" :key="course.id" :value="course.id">{{ course.code }} · {{ course.name_th }}</option></select></div><div class="col-md-2"><button class="btn btn-outline-purple w-100" @click="previewMerge">ตรวจสอบ</button></div></div><div v-if="mergePreview" class="review-box"><p class="mb-2">ย้าย {{ mergePreview.offerings_to_move }} กลุ่มเรียน และเก็บ {{ mergePreview.reviews_preserved }} รีวิว จาก <strong>{{ mergePreview.source_code }}</strong> ไปยัง <strong>{{ mergePreview.target_code }}</strong></p><button class="btn btn-purple" @click="confirmMerge">ยืนยันการรวม</button></div>
        <h2 class="h4 mt-4">ภาคการศึกษาและกลุ่มเรียน</h2><div class="row g-2 mb-3"><div class="col-md-4"><input v-model.number="periodYear" class="form-control" type="number" aria-label="ปีการศึกษา"></div><div class="col-md-5"><input v-model="periodSemester" class="form-control" aria-label="ภาคการศึกษา"></div><div class="col-md-3"><button class="btn btn-outline-purple w-100" @click="addPeriod">เพิ่มภาคการศึกษา</button></div></div><p class="text-muted">{{ periods.map((period) => `${period.semester}/${period.academic_year}`).join(' · ') || 'ยังไม่มีภาคการศึกษา' }}</p><div class="row g-2"><div class="col-md-4"><select v-model="offeringCourseId" class="form-select" @change="loadCourseOfferings"><option value="">รายวิชา</option><option v-for="course in managedCourses.filter((course) => course.status === 'approved')" :key="course.id" :value="course.id">{{ course.code }}</option></select></div><div class="col-md-2"><input v-model.number="offeringYear" class="form-control" type="number" aria-label="ปีการศึกษา"></div><div class="col-md-2"><input v-model="offeringSemester" class="form-control" placeholder="ภาค"></div><div class="col-md-2"><input v-model="offeringSection" class="form-control" placeholder="กลุ่ม"></div><div class="col-md-2"><select v-model.number="offeringDay" class="form-select"><option v-for="day in [1,2,3,4,5,6,7]" :key="day" :value="day">{{ dayNames[day] }}</option></select></div><div class="col-md-4"><input v-model="offeringInstructor" class="form-control" placeholder="ผู้สอน"></div><div class="col-md-3"><input v-model="offeringStart" class="form-control" type="time"></div><div class="col-md-3"><input v-model="offeringEnd" class="form-control" type="time"></div><div class="col-md-2"><button class="btn btn-purple w-100" @click="addOffering">{{ editingOfferingId ? 'บันทึกกลุ่มเรียน' : 'เพิ่มกลุ่มเรียน' }}</button></div></div><div v-if="offeringCourseId" class="mt-2"><p v-if="!courseOfferings.length" class="text-muted">ยังไม่มีกลุ่มเรียนสำหรับรายวิชานี้</p><ul v-else class="list-group"><li v-for="offering in courseOfferings" :key="offering.id" class="list-group-item d-flex justify-content-between align-items-center"><span>กลุ่ม {{ offering.section }} · {{ offering.semester }}/{{ offering.academic_year }}<small v-if="offering.instructor_name" class="text-muted"> · {{ offering.instructor_name }}</small></span><button class="btn btn-sm btn-outline-purple" @click="editOffering(offering)">แก้ไข</button></li></ul></div>
        <h2 class="h4 mt-4">นำเข้ากลุ่มเรียนจำนวนมาก</h2><p class="text-muted mb-2">วางข้อมูลเป็นรายการ JSON ของกลุ่มเรียน เช่น <code>[{"courseCode":"JC100","academicYear":2569,"semester":"1","section":"2","instructorName":"อาจารย์เอ","dayOfWeek":2,"startsAt":"09:00","endsAt":"11:00"}]</code></p><textarea v-model="bulkImportText" class="form-control mb-2" rows="4" aria-label="ข้อมูลนำเข้ากลุ่มเรียน (JSON)" placeholder='[{"courseCode":"JC100","academicYear":2569,"semester":"1","section":"2","instructorName":"อาจารย์เอ","dayOfWeek":2,"startsAt":"09:00","endsAt":"11:00"}]'></textarea><div class="d-flex gap-2 mb-3"><button class="btn btn-outline-purple" :disabled="!bulkImportText.trim()" @click="previewBulkImport">ตรวจสอบ</button><button class="btn btn-purple" :disabled="!bulkImportPreview.length" @click="confirmBulkImport">ยืนยันนำเข้า</button></div><p v-if="bulkImportResult" class="alert alert-success">นำเข้าสำเร็จ: เพิ่มใหม่ {{ bulkImportResult.created_count }} · แก้ไข {{ bulkImportResult.updated_count }} · ไม่เปลี่ยนแปลง {{ bulkImportResult.existing_count }}</p><div v-if="bulkImportPreview.length" class="table-responsive mb-3"><table class="table table-sm align-middle"><thead><tr><th>แถว</th><th>วิชา</th><th>ภาค/ปี</th><th>กลุ่ม</th><th>สถานะ</th><th>หมายเหตุ</th></tr></thead><tbody><tr v-for="row in bulkImportPreview" :key="row.rowNumber"><td>{{ row.rowNumber }}</td><td>{{ row.courseCode }}</td><td>{{ row.semester }}/{{ row.academicYear }}</td><td>{{ row.section }}</td><td><span :class="row.valid ? 'text-success' : 'text-danger'">{{ row.valid ? (row.action === 'create' ? 'เพิ่มใหม่' : row.action === 'update' ? 'แก้ไข' : 'ไม่เปลี่ยนแปลง') : 'ผิดพลาด' }}</span></td><td class="text-muted">{{ row.reason }}</td></tr></tbody></table></div>
        <h2 class="h4 mt-4">ข้อเสนอกลุ่มเรียน</h2><p v-if="!proposals.length" class="text-muted">ไม่มีข้อเสนอที่รอตรวจสอบ</p><div v-for="proposal in proposals" :key="proposal.id" class="review-box"><div class="d-flex flex-wrap justify-content-between gap-2 align-items-center"><span><strong>{{ proposal.course_code }}</strong> · กลุ่ม {{ proposal.section }} · {{ proposal.semester }}/{{ proposal.academic_year }}<small v-if="proposal.instructor_name" class="d-block text-muted">{{ proposal.instructor_name }}</small></span><span class="d-flex gap-2"><button class="btn btn-sm btn-outline-danger" @click="resolveProposal(proposal.id, false)">ปฏิเสธ</button><button class="btn btn-sm btn-purple" @click="resolveProposal(proposal.id, true)">อนุมัติ</button></span></div></div>
        <h2 class="h4 mt-4">ตรวจสอบรีวิว</h2><div class="row g-2 mb-3"><div class="col-md-5"><input v-model="moderationSearch" class="form-control" placeholder="ค้นหาข้อความรีวิว" aria-label="ค้นหาข้อความรีวิว"></div><div class="col-md-4"><select v-model="moderationState" class="form-select" aria-label="สถานะรีวิว"><option value="all">ทุกสถานะ</option><option value="visible">เผยแพร่</option><option value="hidden">ซ่อน</option><option value="removed">นำออก</option></select></div><div class="col-md-3"><button class="btn btn-outline-purple w-100" @click="loadModerationReviews">ค้นหา</button></div></div><p v-if="!visibleModerationReviews.length" class="text-muted">ไม่พบรีวิว</p><article v-for="review in visibleModerationReviews" :key="review.id" class="review-box"><div class="d-flex justify-content-between gap-2"><span class="stars">{{ '★'.repeat(review.rating) }}</span><small>{{ moderationStateLabel(review.moderation_state) }}<span v-if="!review.author_active"> · ผู้เขียนถอนการเผยแพร่</span></small></div><p class="mb-2">{{ review.text }}</p><input v-model="moderationReasons[review.id]" class="form-control mb-2" placeholder="เหตุผลสำหรับการเปลี่ยนสถานะ" :aria-label="`เหตุผลสำหรับรีวิว ${review.id}`"><div class="d-flex flex-wrap gap-2"><button v-if="review.moderation_state !== 'visible'" class="btn btn-sm btn-outline-purple" @click="moderateReview(review.id, 'visible')">คืนสถานะ</button><button v-if="review.moderation_state !== 'hidden'" class="btn btn-sm btn-outline-danger" @click="moderateReview(review.id, 'hidden')">ซ่อน</button><button v-if="review.moderation_state !== 'removed'" class="btn btn-sm btn-outline-danger" @click="moderateReview(review.id, 'removed')">นำออก</button><button class="btn btn-sm btn-outline-secondary" @click="toggleModerationAudit(review.id)"><i class="bi bi-clock-history me-1"></i>{{ moderationAuditId === review.id ? 'ซ่อนประวัติ' : 'ประวัติการตรวจสอบ' }}</button></div><div v-if="moderationAuditId === review.id" class="mt-3 border-top pt-3"><p v-if="!moderationAudit.length" class="text-muted mb-0">ยังไม่เคยมีการเปลี่ยนสถานะ</p><div v-for="entry in moderationAudit" :key="entry.id" class="mb-2"><small class="text-muted d-block">{{ entry.createdAt }} · {{ entry.actorName }}</small><span>{{ moderationStateLabel(entry.priorState) }} → {{ moderationStateLabel(entry.newState) }}</span><p class="mb-0 text-break">{{ entry.reason }}</p></div></div></article>
        <template v-if="accessRole === 'owner'"><h2 class="h4 mt-4">ผู้ดูแลระบบ</h2><p class="text-muted">กำหนดสิทธิ์ให้บัญชี Google ที่ยืนยันแล้วเท่านั้น</p><div class="review-box"><div v-for="member in members" :key="member.id" class="d-flex justify-content-between align-items-center border-bottom py-2"><span><strong>{{ member.name || member.email }}</strong> <small class="text-muted">{{ member.role }}</small></span><button v-if="member.role === 'administrator'" class="btn btn-sm btn-outline-danger" @click="revokeAdministrator(member.id)">ถอนสิทธิ์</button></div><p v-if="!members.length" class="text-muted mb-0">ยังไม่มีผู้ดูแลเพิ่มเติม</p></div><h3 class="h5">บัญชีที่ยืนยันแล้ว</h3><div class="review-box"><div v-for="account in verifiedAccounts.filter((account) => !members.some((member) => member.id === account.id))" :key="account.id" class="d-flex justify-content-between align-items-center border-bottom py-2"><span>{{ account.name || account.email }}</span><button class="btn btn-sm btn-purple" @click="grantAdministrator(account.id)">แต่งตั้งผู้ดูแล</button></div><p v-if="!verifiedAccounts.filter((account) => !members.some((member) => member.id === account.id)).length" class="text-muted mb-0">ไม่มีบัญชีที่รอการแต่งตั้ง</p></div></template>
      </section>
      <section v-else-if="timetable">
        <div class="d-flex justify-content-between align-items-center mb-4 border-bottom pb-3"><div><h1 class="h3 text-purple">ตารางเรียนส่วนตัว</h1><p class="text-muted mb-0">ตารางนี้ผูกกับบัญชีของคุณ</p></div><div class="d-flex gap-2"><button class="btn btn-outline-danger" @click="clearTimetable">ล้างตาราง</button><button class="btn btn-purple" @click="timetable = false">หน้าหลัก</button></div></div>
        <p v-if="error" class="text-danger" role="alert">{{ error }}</p>
        <LegacyTimetableImport v-if="signedInEmail && neon" :email="signedInEmail" :catalog="courses" :client="neon as any" @imported="refreshTimetableAfterImport" />
        <div v-if="!timetableEntries.length" class="review-box text-center py-5"><h2 class="h4 text-purple">ตารางเรียนยังว่างเปล่า</h2><p class="text-muted">กลับไปที่หน้าหลัก แล้วเพิ่มกลุ่มเรียนที่ต้องการ</p><button class="btn btn-purple" @click="timetable = false">ไปเลือกวิชาเรียน</button></div>
        <template v-else><div class="timetable-container"><div class="timetable-grid"><div class="time-header-row"><div v-for="hour in 12" :key="hour" class="time-header-slot">{{ String(hour + 7).padStart(2, '0') }}:00</div></div><div v-for="day in [1,2,3,4,5,6,7]" :key="day" class="day-row"><div class="day-label">{{ dayNames[day] }}</div><div class="day-track"><div v-for="entry in timetableEntries.filter((item) => item.day_of_week === day)" :key="`${entry.offering_id ?? entry.review_id}-${day}`" class="timetable-course" :class="courseColor(entry.course_code)" :style="timetableStyle(entry)"><strong>{{ entry.course_code }} ({{ entry.section }})</strong><span>{{ timeValue(entry.starts_at) }}–{{ timeValue(entry.ends_at) }}</span><small v-if="entry.source === 'reported'">ข้อมูลจากรีวิว</small></div></div></div></div></div><div class="review-box"><h2 class="h5">รายวิชาที่เลือก</h2><div v-for="entry in timetableEntries.filter((item, index, items) => items.findIndex((other) => (other.offering_id ?? other.review_id) === (item.offering_id ?? item.review_id)) === index)" :key="entry.offering_id ?? entry.review_id!" class="d-flex justify-content-between align-items-center border-bottom py-2"><span><strong>{{ entry.course_code }}</strong> {{ entry.course_name }} · กลุ่ม {{ entry.section }}<small v-if="entry.source === 'reported'" class="text-muted"> · ข้อมูลจากรีวิว</small></span><button class="btn btn-sm btn-outline-danger" @click="removeFromTimetable(entry)">ลบออก</button></div></div></template>
      </section>
      <section v-else-if="myReviewsScreen"><div class="d-flex justify-content-between align-items-center mb-4 border-bottom pb-3"><div><h1 class="h3 text-purple"><i class="bi bi-star-fill text-warning me-2"></i>รีวิวของฉัน</h1><p class="text-muted mb-0">จัดการรีวิวทั้งหมดที่คุณเคยเขียนไว้ที่นี่</p></div><button class="btn btn-purple shadow-sm" @click="myReviewsScreen = false"><i class="bi bi-arrow-left-circle-fill me-1"></i>หน้าหลัก</button></div><p v-if="error" class="text-danger" role="alert">{{ error }}</p><p v-if="!myReviews.length" class="review-box text-muted">คุณยังไม่เคยเขียนรีวิว</p><article v-for="review in myReviews" :key="review.id" class="review-box"><h5 class="text-purple fw-bold mb-1">รีวิวของฉัน</h5><div class="d-flex justify-content-between align-items-center mb-3"><span class="stars">{{ '★'.repeat(review.rating) }}</span><span class="badge bg-light text-dark border">{{ review.active ? 'เผยแพร่แล้ว' : 'ถอนการเผยแพร่' }}</span></div><template v-if="editingReviewId === review.id"><label class="form-label" :for="`edit-rating-${review.id}`">คะแนนรวม</label><select :id="`edit-rating-${review.id}`" v-model="editReviewRating" class="form-select mb-3"><option v-for="n in 5" :key="n" :value="n">{{ n }} ดาว</option></select><label class="form-label" :for="`edit-text-${review.id}`">ความคิดเห็น</label><textarea :id="`edit-text-${review.id}`" v-model="editReviewText" class="form-control mb-3" rows="3"></textarea><div class="d-flex gap-2"><button class="btn btn-outline-secondary" @click="cancelReviewEdit">ยกเลิก</button><button class="btn btn-purple" @click="saveReviewEdit">บันทึก</button></div></template><template v-else><p class="text-break">{{ review.text }}</p><div class="d-flex justify-content-between align-items-end mt-4"><small class="text-muted"><i class="bi bi-clock me-1"></i>{{ review.createdAt }}</small><div class="d-flex gap-2"><button class="btn btn-sm btn-outline-purple px-3 rounded-pill" @click="beginReviewEdit(review)"><i class="bi bi-pencil-fill me-1"></i>แก้ไข</button><button v-if="review.active" class="btn btn-sm btn-outline-danger px-3 rounded-pill" @click="setMyReviewActive(review.id, false)">ถอนรีวิว</button><button v-else class="btn btn-sm btn-purple px-3 rounded-pill" @click="setMyReviewActive(review.id, true)">เผยแพร่อีกครั้ง</button><button class="btn btn-sm btn-outline-secondary px-3 rounded-pill" @click="toggleReviewHistory(review.id)"><i class="bi bi-clock-history me-1"></i>{{ reviewHistoryId === review.id ? 'ซ่อนประวัติ' : 'ดูประวัติการแก้ไข' }}</button></div></div><div v-if="reviewHistoryId === review.id" class="mt-3 border-top pt-3"><p v-if="!reviewHistory.length" class="text-muted mb-0">ยังไม่มีการแก้ไขก่อนหน้านี้</p><div v-for="revision in reviewHistory" :key="revision.id" class="mb-2"><small class="text-muted d-block"><span class="stars">{{ '★'.repeat(revision.rating) }}</span> · {{ revision.revisedAt }}</small><p class="mb-0 text-break">{{ revision.text }}</p></div></div></template></article></section>
