        </template>
        <section v-if="selected" class="course-review-modal"><div class="course-review-dialog"><header class="course-review-header"><h1><i class="bi bi-book-half me-2"></i>{{ selected.code }} - {{ selected.name_th }}</h1><button class="btn-close btn-close-white" aria-label="ปิด" @click="selected = null"></button></header><div class="course-review-body"><p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2"><h2 class="section-label mb-0">💬 รีวิวและเวลาเรียน</h2><button class="btn btn-purple btn-sm shadow-sm" @click="reviewFormOpen = !reviewFormOpen"><i class="bi bi-pencil-square me-1"></i>เขียนรีวิว / เพิ่มเซคชั่น</button></div><div v-if="reviewFormOpen" class="review-form-card mb-4"><h3 class="section-label mb-3">✍️ เขียนรีวิว &amp; ข้อมูลเวลาเรียน</h3><div class="row mb-3"><div class="col-md-6 mb-3 mb-md-0"><label for="review-semester">เทอมที่เรียน</label><select id="review-semester" v-model="reviewSemester" class="form-select"><option value="">เลือก...</option><option value="1">เทอม 1</option><option value="2">เทอม 2</option><option value="ฤดูร้อน">ฤดูร้อน</option></select></div><div class="col-md-6"><label for="review-year">ปีการศึกษา</label><select id="review-year" v-model.number="reviewYear" class="form-select"><option :value="0">เลือก...</option><option v-for="year in [2569,2568,2567,2566,2565]" :key="year" :value="year">{{ year }}</option></select></div></div><div class="row mb-3"><div class="col-md-6 mb-3 mb-md-0"><label for="review-teacher">อาจารย์ผู้สอน</label><input id="review-teacher" class="form-control" v-model="reviewTeacher" placeholder="ชื่ออาจารย์"></div><div class="col-md-6"><label for="review-section">กลุ่มเรียน (เช่น Sec 01)</label><input id="review-section" class="form-control" v-model="reviewSection" placeholder="Sec..."></div></div><div class="row mb-3"><div class="col-md-4 mb-3 mb-md-0"><label for="review-day">วัน</label><select id="review-day" v-model="reviewDay" class="form-select"><option v-for="day in dayNames.slice(1)" :key="day" :value="day">{{ day }}</option></select></div><div class="col-md-4 mb-3 mb-md-0"><label for="review-start">เวลาเริ่ม (น.)</label><input id="review-start" class="form-control" v-model="reviewStart" type="time"></div><div class="col-md-4"><label for="review-end">เวลาเลิก (น.)</label><input id="review-end" class="form-control" v-model="reviewEnd" type="time"></div></div><div class="mb-3"><label for="rating">ให้คะแนน (1-5 ดาว)</label><select id="rating" v-model="rating" class="form-select"><option v-for="n in 5" :key="n" :value="n">{{ n }} ดาว</option></select></div><div class="mb-4"><label for="review">ประสบการณ์ที่เจอ</label><textarea id="review" v-model="text" class="form-control" rows="3"></textarea></div><button class="btn btn-purple w-100 py-2" :disabled="publishing" @click="publish"><i class="bi bi-save me-1"></i>{{ publishing ? 'กำลังบันทึก...' : 'บันทึกข้อมูล' }}</button></div><div v-for="offering in offerings" :key="offering.id" class="offering-card mb-3"><div class="d-flex justify-content-between align-items-center gap-2"><span class="offering-term">เทอม {{ offering.semester }}/{{ offering.academic_year }}</span><button class="btn btn-sm btn-success" @click="addToTimetable(offering)"><i class="bi bi-pin-angle-fill me-1"></i>เพิ่มลงตาราง</button></div><div class="offering-meta mt-3"><strong>กลุ่ม {{ offering.section }}</strong><span v-if="offering.instructor_name"> · {{ offering.instructor_name }}</span></div></div><div v-if="false" class="review-box proposal-box"><h2>ไม่พบกลุ่มเรียนที่ต้องการ?</h2><p class="text-muted">เสนอข้อมูลกลุ่มเรียนเพื่อให้ผู้ดูแลตรวจสอบ ข้อเสนอนี้แยกจากการเขียนรีวิว</p><div class="row g-2"><div class="col-md-3"><input v-model.number="proposalYear" type="number" class="form-control" aria-label="ปีการศึกษาที่เสนอ"></div><div class="col-md-2"><input v-model="proposalSemester" class="form-control" placeholder="ภาค"></div><div class="col-md-3"><input v-model="proposalSection" class="form-control" placeholder="กลุ่มเรียน"></div><div class="col-md-4"><input v-model="proposalInstructor" class="form-control" placeholder="ผู้สอน (ถ้าทราบ)"></div></div><button class="btn btn-outline-purple mt-3" @click="submitProposal">ส่งข้อเสนอกลุ่มเรียน</button><div v-if="myProposals.filter((proposal) => proposal.courseId === selected!.id).length" class="mt-3"><h3 class="h6">ข้อเสนอของฉัน</h3><p v-for="proposal in myProposals.filter((item) => item.courseId === selected!.id)" :key="proposal.id" class="mb-1">กลุ่ม {{ proposal.section }} · {{ proposal.semester }}/{{ proposal.academicYear }} <span class="text-muted">{{ proposal.status === 'pending' ? 'กำลังตรวจสอบ' : proposal.status === 'approved' ? 'อนุมัติแล้ว' : 'ไม่อนุมัติ' }}</span></p></div></div><div class="row g-2 mb-3"><div class="col-sm-4"><select v-model.number="reviewRatingFilter" class="form-select" aria-label="กรองคะแนน" @change="loadReviews()"><option :value="0">ทุกคะแนน</option><option v-for="score in 5" :key="score" :value="score">{{ score }} ดาว</option></select></div><div class="col-sm-4"><select v-model="reviewSemesterFilter" class="form-select" aria-label="กรองภาคการศึกษา" @change="loadReviews()"><option value="">ทุกเทอม</option><option value="1">เทอม 1</option><option value="2">เทอม 2</option><option value="ฤดูร้อน">ฤดูร้อน</option></select></div><div class="col-sm-4"><select v-model.number="reviewYearFilter" class="form-select" aria-label="กรองปีการศึกษา" @change="loadReviews()"><option :value="0">ทุกปี</option><option v-for="year in [2569,2568,2567,2566,2565]" :key="year" :value="year">{{ year }}</option></select></div></div><p v-if="!reviews.length" class="review-empty">ยังไม่มีรีวิว</p><article v-for="review in reviews" :key="review.id" class="review-box review-card"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3"><div class="d-flex align-items-center gap-2"><span class="stars">{{ '★'.repeat(review.rating) }}</span><span v-if="review.semester && review.academicYear" class="offering-term">เทอม {{ review.semester }}/{{ review.academicYear }}</span></div><span v-if="reviewDate(review.createdAt)" class="text-muted small"><i class="bi bi-clock me-1"></i>{{ reviewDate(review.createdAt) }}</span></div><div v-if="review.section" class="review-schedule sec-info-box"><div class="review-schedule-top"><div><span class="text-muted fw-semibold">กลุ่ม {{ review.section }}</span><span v-if="review.instructorName" class="fw-bold ms-2 text-dark"><i class="bi bi-person-video3 me-1"></i>{{ review.instructorName }}</span></div><button v-if="(reviewOffering(review) || hasReportedTime(review)) && !isReviewSelected(review)" class="btn btn-sm btn-success" @click="addReviewToTimetable(review)"><i class="bi bi-pin-angle-fill me-1"></i>เพิ่มลงตาราง</button><span v-else-if="isReviewSelected(review)" class="text-success fw-bold">อยู่ในตารางแล้ว</span></div><p v-if="review.dayOfWeek && review.startsAt && review.endsAt" class="mb-1 text-muted schedule-line"><i class="bi bi-calendar-event me-1"></i>วัน{{ dayNames[review.dayOfWeek] }} | ⏰ {{ timeValue(review.startsAt) }} - {{ timeValue(review.endsAt) }} น.</p><p v-if="reviewOffering(review)" class="small text-muted mb-1">ข้อมูลกลุ่มเรียนที่อนุมัติ · {{ offeringMeetings[reviewOffering(review)!.id].map((meeting) => `${dayNames[meeting.day]} ${meeting.start}–${meeting.end}`).join(' · ') }}<span v-if="reviewOffering(review)!.instructor_name"> · {{ reviewOffering(review)!.instructor_name }}</span></p><p v-else-if="!hasReportedTime(review)" class="small text-muted mb-1">รีวิวนี้ไม่มีข้อมูลเวลาเรียนที่ใช้เพิ่มลงตารางได้</p></div><p class="mt-3 mb-0">{{ review.text }}</p></article></div></div></section>
      </template>
    </section>
    <button v-if="signedIn" class="btn btn-purple floating-contact-btn" :aria-expanded="contactOpen" @click="contactOpen = !contactOpen"><i class="bi bi-chat-heart-fill fs-5"></i><span class="d-none d-md-inline ms-1">แจ้งปัญหา/ติดต่อ</span></button>
    <div v-if="signedIn && contactOpen" class="contact-panel" role="dialog" aria-modal="true" aria-label="ติดต่อผู้ดูแล"><div class="contact-modal-card"><div class="contact-modal-header"><h5 class="modal-title text-purple mb-0"><i class="bi bi-headset me-2"></i>ติดต่อผู้ดูแล</h5><button class="btn-close" aria-label="ปิด" @click="contactOpen = false"></button></div><div class="contact-modal-body"><a href="https://line.me/R/ti/p/@293shldn" target="_blank" rel="noopener noreferrer" class="btn contact-line text-white fw-bold w-100 mb-3"><i class="bi bi-line fs-5 me-2"></i>ติดต่อทาง LINE</a><a href="https://www.instagram.com/varasarn_official" target="_blank" rel="noopener noreferrer" class="btn contact-instagram text-white fw-bold w-100"><i class="bi bi-instagram fs-5 me-2"></i>ทักแชททาง IG</a></div></div></div>
  </main>
</template>
